/* P-RAPORT rata 4a (2026-09-20): role zdan. Trzy dolne kolumny raportu pacjenta
   („Na talerzu", „Ruch", „Kontrola") musza pokazywac ZDANIE GENERATORA, a nie parafraze —
   inaczej nowy raport zaczyna przeczyc raportowi tekstowemu na krancach wieku (2–4 lata maja
   ruch 180 min/d i limit ekranu, a nie 60 min/d). Znacznik zapisuje indeks, pod ktorym za
   chwile stanie zdanie danej roli. Stoi w TYM SAMYM wyrazeniu co push — zapis
   `(vildaRola(x,"ruch"),x).push(...)` podstawia wyrazenie w miejsce identyfikatora tablicy,
   wiec priorytety operatorow (np. `warunek&&x.push(...)`) zostaja nietkniete, a znacznik
   wykonuje sie dokladnie wtedy, kiedy push. */
  /* P-DIETA-AUDYT rata F (2026-09-21): powody z modulu ryzyka (vilda_anorexia_risk.js) przelozone na krotkie
     frazy do zdania o nadzorze. Zadnego progu tu nie ma — kryteria i liczby zostaja w module ryzyka. */
  function vildaPowodyRyzykaZO(reasons) {
    var out = [];
    (Array.isArray(reasons) ? reasons : []).forEach(function(r) {
      var t = String(r || ""), m, f = null;
      if ((m = t.match(/Masa < (\d+)%/))) f = "masa poniżej " + m[1] + " % należnej";
      else if (/2\. centyla/.test(t)) f = "BMI poniżej 2. centyla";
      else if (/utrata|spadek/i.test(t)) f = "szybka utrata masy ciała";
      else if ((m = t.match(/BMI < (\d+(?:\.\d+)?)/))) f = "BMI poniżej " + m[1].replace(".", ",");
      else if (/Skrajnie niskie BMI/.test(t)) f = "skrajnie niskie BMI";
      else if (/niedożywienie/.test(t)) f = "BMI poniżej 85 % mediany dla wieku";
      f && out.indexOf(f) === -1 && out.push(f);
    });
    return out.join("; ");
  }

